  bind('[data-act="b47"]', 'click', () => { setGridColor('rgba(0,150,255,__A__)'); });
  bind('[data-act="b48"]', 'click', () => { setGridColor('rgba(255,50,50,__A__)'); });
  bind('[data-act="b49"]', 'click', () => { resetProjection(); });
  bind('#btn-tokgrid', 'click', () => { toggleTokenGrid(); });
  bind('#tokgrid-color', 'input', () => { setTokenGridColor(); });
  bind('#tokgrid-opacity', 'input', () => { setTokenGridColor(); });
  bind('#btn-key-square', 'click', () => { setKeyShape('square'); });
  bind('#btn-key-hex', 'click', () => { setKeyShape('hex'); });
  bind('#btn-key-hexflat', 'click', () => { setKeyShape('hexflat'); });
  bind('#key-cell', 'input', (_e, el) => { setKeyCell(el.value); });
  bind('[data-act="b50"]', 'click', () => { nudgeKeyCell(-1); });
  bind('[data-act="b51"]', 'click', () => { nudgeKeyCell(-0.1); });
