  bind('#key-ox', 'input', (_e, el) => { setKeyOx(el.value); });
  bind('#key-oy', 'input', (_e, el) => { setKeyOy(el.value); });
  bind('[data-act="b58"]', 'click', () => { nudgeKeyOrigin(-1,0); });
  bind('[data-act="b59"]', 'click', () => { nudgeKeyOrigin(1,0); });
  bind('[data-act="b60"]', 'click', () => { nudgeKeyOrigin(0,-1); });
  bind('[data-act="b61"]', 'click', () => { nudgeKeyOrigin(0,1); });
